 "content": "def transform(grid):
    """Extend exposed diagonal pairs of matching colors through background to edges."""
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    out = [row[:] for row in grid]
    rays = set()

    def embedded_in_filled_square(r1, c1, r2, c2):
        # Ignore a pair that is simply one diagonal of a fully occupied 2x2 motif.
        for top in (r1 - 1, r1, r2 - 1, r2):
            for left in (c1 - 1, c1, c2 - 1, c2):
                if 0 <= top < h - 1 and 0 <= left < w - 1:
                    cells = (grid[top][left], grid[top + 1][left],
                             grid[top][left + 1], grid[top + 1][left + 1])
                    if all(v != bg for v in cells):
                        if (r1 in (top, top + 1) and c1 in (left, left + 1)
                                and r2 in (top, top + 1) and c2 in (left, left + 1)):
                            return True
        return False

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                r2, c2 = r + dr, c + dc
                if not (0 <= r2 < h and 0 <= c2 < w) or grid[r2][c2] != color:
                    continue
                if embedded_in_filled_square(r, c, r2, c2):
                    continue
                for sr, sc, vr, vc in ((r, c, -dr, -dc), (r2, c2, dr, dc)):
                    rr, cc = sr + vr, sc + vc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
